export type CitationScope = '经文' | '解读' | '背景' | '串联' | '应用';

export type StudyCitation = {
  id: string;
  label: string;
  url: string;
  scope: CitationScope;
};

export type StudyNote = {
  range: string;
  title: string;
  scripture: string;
  scene: string;
  literal: string;
  context: string;
  connection?: string;
  life?: string;
  citations?: StudyCitation[];
};

