export function applyResearchReview(note: StudyNote): StudyNote {
  const override = researchReviewOverrides[note.range];
  return override ? { ...note, ...override } : note;
}

function n(range: string, title: string, scene: string, scripture: string, literal: string, context: string, connection: string, life: string): StudyNote {
  return { range, title, scene, scripture, literal, context, connection, life };
}

